def filter_words(string_list):
    """
    :param string_list: A list of strings.
    :return: A list of filtered strings.
    """
    # 1. Create a dictionary to store the first and last letters of each word.
    first_letters = {}
    last_letters = {}
    for word in string_list:
        first_letters[word[0]] = word[0]
        last_letters[word[-1]] = word[-1]

    # 2. Filter out all words that have the same first letter and last letter.
    filtered_list = []
    for word in string_list:
        if word[0] in first_letters and word[-1] in last_letters:
            filtered_list.append(word)

    return filtered_list


