def isbn_valid(isbn):
    """
    Check if an ISBN is valid according to the ISBN-10 standard.

    :param isbn: A 13-digit ISBN-10 number.
    :return: True if the ISBN is valid, False otherwise.
    """
    # Check if the ISBN is a valid 10-digit number
    if len(isbn) != 10:
        return False

    # Check if the ISBN contains only digits
    for digit in isbn:
        if not digit.isdigit():
            return False

    # Check if the ISBN contains only digits and hyphens
    for digit in isbn:
        if digit.isdigit() and digit.isdigit() and digit != '-':
            return False

    # Check if the ISBN contains only hyphens
    for hyphen in isbn:
        if hyphen.isdigit():
            return False

    return True
